export class Scanner {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
  }

  peek(offset = 0) {
    return this.source[this.pos + offset];
  }

  advance() {
    const char = this.peek();
    if (char === '\n') {
      this.line++;
      this.column = 1;
    } else if (char === '\t') {
      this.column = Math.floor((this.column - 1 + 4) / 4) * 4 + 1;
    } else if (char !== undefined) {
      this.column++;
    }
    this.pos++;
    return char;
  }

  skipWhitespace() {
    while (this.pos < this.source.length) {
      const char = this.peek();
      if (char === ' ' || char === '\t' || char === '\r' || char === '\n') {
        this.advance();
      } else {
        break;
      }
    }
  }

  skipLineComment() {
    // Skip //
    this.advance();
    this.advance();
    // Skip until newline or end
    while (this.pos < this.source.length && this.peek() !== '\n') {
      this.advance();
    }
  }

  skipBlockComment() {
    const startLine = this.line;
    const startCol = this.column;
    let depth = 1;

    // Skip /*
    this.advance();
    this.advance();

    while (this.pos < this.source.length && depth > 0) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance();
        this.advance();
        depth++;
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance();
        this.advance();
        depth--;
      } else {
        this.advance();
      }
    }

    if (depth > 0) {
      throw new ScannerError(`unterminated block comment`, startLine, startCol);
    }
  }

  readIdentifier() {
    const startCol = this.column;
    let value = '';
    while (
      this.pos < this.source.length &&
      /[a-zA-Z0-9_]/.test(this.peek())
    ) {
      value += this.advance();
    }
    return { value, col: startCol };
  }

