    const startCol = this.column;
    let value = '';

    // Handle prefixes
    if (this.peek() === '0' && /[xXbBoO]/.test(this.peek(1))) {
      value += this.advance(); // '0'
      const prefix = this.peek().toLowerCase();
      value += this.advance(); // x, b, or o

      // Read digits with allowed underscores
