      while (this.pos < this.source.length) {
        if (digitPattern.test(this.peek())) {
          value += this.advance();
          hasDigit = true;
        } else if (this.peek() === '_' && digitPattern.test(this.peek(1))) {
          this.advance(); // consume underscore
          value += this.advance();
        } else {
          break;
        }
      }

      if (!hasDigit) {
        // No digits after prefix - invalid
        value += this.readInvalidNumberTail();
        throw new ScannerError(`invalid number ${value}`, this.line, startCol);
