      let hasDigit = false;

      // Read integer part
      while (this.pos < this.source.length) {
        if (/[0-9]/.test(this.peek())) {
          value += this.advance();
          hasDigit = true;
        } else if (this.peek() === '_' && /[0-9]/.test(this.peek(1))) {
          this.advance(); // consume underscore
          value += this.advance();
        } else {
          break;
        }
      }

